:root{--bg:#0b0d0c;--fg:#f1f3ea;--muted:#8b9788;--line:#29312a;--side:#101311;--link:#c3f36b;--code:#131714;--k:#ff79c6;--t:#5ce1e6;--e:#ffb638;--o:#b3bbae;--l:#c3f36b;--n:#ff9f5a;--s:#6bffab;--c:#8b9e8d;--d:#8b9e8d;--a:#c49bff;--x:#ff6b6b}
@media(prefers-color-scheme:light){:root{--bg:#f6f5ef;--fg:#0f1f16;--muted:#5b695f;--line:#d4dacb;--side:#eeeee5;--link:#3c6514;--code:#fdfdf8;--k:#a626a4;--t:#0b6e6e;--e:#945700;--o:#33463a;--l:#3c6514;--n:#b35c00;--s:#1f7a3a;--c:#5b695f;--d:#5b695f;--a:#7a3fa8;--x:#b3261e}}
*{box-sizing:border-box}
html{font-size:17px}
body{margin:0;background:var(--bg);color:var(--fg);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;line-height:1.55}
a{color:var(--link);text-decoration:none}
a:hover{text-decoration:underline}
nav.side{position:fixed;top:0;left:0;bottom:0;width:17rem;overflow-y:auto;padding:1.25rem 1rem;background:var(--side);border-right:1px solid var(--line);font-size:.92rem}
nav.side .brand{font-weight:700;font-size:1.1rem;margin:0 0 1rem}nav.side .brand-logo{width:2.2rem;height:2.2rem;fill:var(--link);display:block}
nav.side h2{font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:1.2rem 0 .35rem}
nav.side ul{list-style:none;margin:0;padding:0}
nav.side li{margin:.15rem 0}
nav.side a{color:var(--fg)}
nav.side a.here{font-weight:700;color:var(--link)}
main{max-width:46rem;margin:0 auto;padding:2rem 1.25rem 4rem;margin-left:19rem}
@media(max-width:62rem){nav.side{position:static;width:auto;border-right:0;border-bottom:1px solid var(--line);padding:1rem}main{margin-left:auto;padding:1.5rem 1rem 3rem}}
h1,h2,h3,h4{line-height:1.25;margin:1.6em 0 .5em}
h1{font-size:1.9rem;margin-top:.2em}
h2{font-size:1.4rem;border-bottom:1px solid var(--line);padding-bottom:.2em}
h3{font-size:1.12rem}
p,ul,ol,blockquote,table,pre{margin:0 0 1em}
li{margin:.2em 0}
li>ul,li>ol{margin-bottom:0}
code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.92em;background:var(--code);padding:.08em .3em;border-radius:3px}
pre{background:var(--code);padding:.8em 1em;border-radius:6px;overflow-x:auto;line-height:1.45}
pre code{background:none;padding:0;font-size:.88em}
blockquote{border-left:3px solid var(--line);margin-left:0;padding-left:1em;color:var(--muted)}
table{border-collapse:collapse;width:100%;font-size:.94em;display:block;overflow-x:auto}
th,td{border:1px solid var(--line);padding:.35em .6em;text-align:left;vertical-align:top}
th{background:var(--side)}
hr{border:0;border-top:1px solid var(--line);margin:2em 0}
img{max-width:100%}
.path{color:var(--muted);margin-top:-.6em}
.decl{margin:1.5em 0;padding-top:.4em;border-top:1px solid var(--line)}
.decl h3{margin:.4em 0 .5em}
.decl h3 a{color:var(--fg)}
.kind{font-size:.75rem;font-weight:400;color:var(--muted);margin-left:.6em;text-transform:uppercase;letter-spacing:.05em}
.nodoc{color:var(--x);font-style:italic}
.k{color:var(--k);font-weight:600}
.t{color:var(--t)}
.e{color:var(--e)}
.o{color:var(--o)}
.l{color:var(--l)}
.n{color:var(--n)}
.s{color:var(--s)}
.c{color:var(--c);font-style:italic}
.d{color:var(--d);font-style:italic}
.a{color:var(--a)}
.x{color:var(--x);text-decoration:underline wavy}

